/**
 * Override the activity completion define js.
 *
 * @module   dashaddon_activity_completion
 * @copyright  2023 bdecent gmbh <https://bdecent.de>
 * @license   http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("dashaddon_activity_completion/toggle_completion",["core/fragment","core/modal_factory","core/modal_events","core/notification","core/str","core/ajax"],(function(Fragment,ModalFactory,ModalEvents,notification,String,Ajax){

    /**
     * Override the activity completion in the activity completion data source.
     */
    function togglecompletion() {
        const seletor = document.querySelectorAll(".activity-completion-override .custom-control");
        //console.log(seletor);
        seletor.forEach((button) => {
            button.addEventListener('click', function(e) {
                e.preventDefault();
                var cmid = e.currentTarget.getAttribute("data-cmid");
                var userid = e.currentTarget.getAttribute("data-userid");
                var state = e.currentTarget.getAttribute("data-state");
                var overrideuser = e.currentTarget.getAttribute("data-overrideuser");
                var cmcid = e.currentTarget.getAttribute("data-cmcid");
                ModalFactory.create({
                    type: ModalFactory.types.SAVE_CANCEL,
                    title: String.get_string('confirm'),
                    body: String.get_string('completionstate', 'dashaddon_activity_completion'),
                    large: false
                })
                .then(function(modal) {
                    modal.show();
                    modal.getRoot().on(ModalEvents.save, e => {
                        e.preventDefault();
                        modal.getRoot().find('form').submit();
                        overridestatus(cmid, userid, state, overrideuser, cmcid);
                        modal.hide();
                    });

                    // modal.getRoot().on('submit', 'form', e => {
                    //     e.preventDefault();
                    // });

                    modal.getRoot().on(ModalEvents.hidden, function() {
                        modal.destroy();
                    });
                    //return modal;
                }).catch(notification.exception);
            });
        });
    }

    /**
     * Override the activity completion status.
     *
     * @param {int} cmid
     * @param {int} userid
     * @param {int} state
     * @param {int} overrideuser
     * @param {int} cmcid
     */
    function overridestatus(userid, cmid, state, overrideuser, cmcid) {
        Ajax.call([{
            methodname: 'dashaddon_activity_completion_override_completion_status',
            args: {cmid: cmid, userid: userid, state: state, overrideuser: overrideuser, cmcid: cmcid},
            done: function(response) {
                if (response.status) {
                    window.setTimeout(function() {
                        window.location.reload();
                    }, 500);
                }
            }
        }]);
    }

    return {
        init: function() {
            togglecompletion();
        }
    };


}));

